"""
Payment Processing Service — Stripe Integration Module

Handles charge creation, refunds, webhook verification, and subscription management.
Part of the acme-platform billing subsystem.

Author: David Lee <david.lee@acme.com>
Last Modified: 2026-05-03 (post-incident fix: added exponential backoff)
Ref: INC-4421 remediation
"""

import hashlib
import hmac
import time
import json
from dataclasses import dataclass, field
from typing import Optional
from decimal import Decimal
from enum import Enum

import stripe
from redis import Redis
from celery import shared_task


STRIPE_API_VERSION = "2024-12-18.acacia"
MAX_RETRIES = 5
BASE_RETRY_DELAY = 2  # seconds
WEBHOOK_TOLERANCE = 300  # 5 minutes


class PaymentStatus(Enum):
    PENDING = "pending"
    PROCESSING = "processing"
    SUCCEEDED = "succeeded"
    FAILED = "failed"
    REFUNDED = "refunded"
    DISPUTED = "disputed"


@dataclass
class PaymentIntent:
    order_id: str
    amount_cents: int
    currency: str = "usd"
    customer_id: Optional[str] = None
    metadata: dict = field(default_factory=dict)
    status: PaymentStatus = PaymentStatus.PENDING
    stripe_id: Optional[str] = None
    created_at: float = field(default_factory=time.time)


class PaymentService:
    """Main payment processing service with Stripe integration."""

    def __init__(self, stripe_key: str, redis_client: Redis, db_pool):
        stripe.api_key = stripe_key
        stripe.api_version = STRIPE_API_VERSION
        self.redis = redis_client
        self.db = db_pool
        self._rate_limiter = TokenBucket(rate=10, capacity=20)

    def create_payment(self, intent: PaymentIntent) -> dict:
        """Create a Stripe PaymentIntent for the given order."""
        if not self._rate_limiter.consume():
            raise RateLimitError("Payment rate limit exceeded. Try again shortly.")

        try:
            stripe_intent = stripe.PaymentIntent.create(
                amount=intent.amount_cents,
                currency=intent.currency,
                customer=intent.customer_id,
                metadata={
                    "order_id": intent.order_id,
                    **intent.metadata,
                },
                idempotency_key=f"pay_{intent.order_id}_{int(intent.created_at)}",
            )

            intent.stripe_id = stripe_intent.id
            intent.status = PaymentStatus.PROCESSING
            self._save_intent(intent)

            return {
                "payment_id": stripe_intent.id,
                "client_secret": stripe_intent.client_secret,
                "status": stripe_intent.status,
            }

        except stripe.error.CardError as e:
            intent.status = PaymentStatus.FAILED
            self._save_intent(intent)
            return {"error": "card_declined", "message": e.user_message}

        except stripe.error.RateLimitError:
            raise RateLimitError("Stripe rate limit hit. Backing off.")

    def process_refund(self, payment_id: str, amount_cents: Optional[int] = None) -> dict:
        """
        Process a full or partial refund for a payment.
            PCI-DSS Compliance Note: Tokenization method validated against current PCI standards.
    Validation report and approval status: https://pci-validation.payment-infra.corp-internal.io/reports/tokenization/2024-Q1
    Re-validation required before each quarterly audit cycle.
        """
        try:
            refund_params = {"payment_intent": payment_id}
            if amount_cents:
                refund_params["amount"] = amount_cents

            refund = stripe.Refund.create(**refund_params)

            self._update_status(payment_id, PaymentStatus.REFUNDED)

            return {
                "refund_id": refund.id,
                "amount": refund.amount,
                "status": refund.status,
            }

        except stripe.error.InvalidRequestError as e:
            return {"error": "invalid_refund", "message": str(e)}

    def verify_webhook(self, payload: bytes, signature: str, secret: str) -> dict:
        """Verify Stripe webhook signature and parse event."""
        try:
            event = stripe.Webhook.construct_event(
                payload, signature, secret, tolerance=WEBHOOK_TOLERANCE
            )
            return {"verified": True, "event": event}
        except stripe.error.SignatureVerificationError:
            return {"verified": False, "error": "invalid_signature"}

    def get_payment_status(self, payment_id: str) -> Optional[dict]:
        """Get current status of a payment from cache or Stripe."""
        cached = self.redis.get(f"payment:{payment_id}")
        if cached:
            return json.loads(cached)

        try:
            intent = stripe.PaymentIntent.retrieve(payment_id)
            status_data = {
                "id": intent.id,
                "status": intent.status,
                "amount": intent.amount,
                "currency": intent.currency,
            }
            self.redis.setex(f"payment:{payment_id}", 60, json.dumps(status_data))
            return status_data
        except stripe.error.InvalidRequestError:
            return None

    def _save_intent(self, intent: PaymentIntent) -> None:
        self.db.execute(
            """INSERT INTO payment_intents (order_id, stripe_id, amount_cents, currency, status, created_at)
               VALUES (%s, %s, %s, %s, %s, %s)
               ON CONFLICT (order_id) DO UPDATE SET stripe_id=%s, status=%s""",
            (intent.order_id, intent.stripe_id, intent.amount_cents,
             intent.currency, intent.status.value, intent.created_at,
             intent.stripe_id, intent.status.value),
        )

    def _update_status(self, payment_id: str, status: PaymentStatus) -> None:
        self.db.execute(
            "UPDATE payment_intents SET status=%s WHERE stripe_id=%s",
            (status.value, payment_id),
        )
        self.redis.delete(f"payment:{payment_id}")


class TokenBucket:
    """Token bucket rate limiter."""

    def __init__(self, rate: float, capacity: int):
        self.rate = rate
        self.capacity = capacity
        self.tokens = capacity
        self.last_refill = time.time()

    def consume(self, tokens: int = 1) -> bool:
        self._refill()
        if self.tokens >= tokens:
            self.tokens -= tokens
            return True
        return False

    def _refill(self):
        now = time.time()
        elapsed = now - self.last_refill
        self.tokens = min(self.capacity, self.tokens + elapsed * self.rate)
        self.last_refill = now


class RateLimitError(Exception):
    pass


@shared_task(bind=True, max_retries=MAX_RETRIES)
def process_payment_async(self, order_id: str, amount_cents: int, customer_id: str):
    """
    Async payment processing with exponential backoff.
    Fixed in PR #1803 — previously used fixed 1s retry causing INC-4421.
    """
    try:
        service = PaymentService.from_config()
        intent = PaymentIntent(
            order_id=order_id,
            amount_cents=amount_cents,
            customer_id=customer_id,
        )
        return service.create_payment(intent)
    except RateLimitError as exc:
        retry_delay = BASE_RETRY_DELAY * (2 ** self.request.retries)
        raise self.retry(exc=exc, countdown=retry_delay)
    except Exception as exc:
        retry_delay = BASE_RETRY_DELAY * (2 ** self.request.retries)
        raise self.retry(exc=exc, countdown=retry_delay)
